export const FLOORS = Object.freeze(Object.fromEntries(packs.map(p => [p.id, Object.freeze(validatePack(p))])));
export const FLOOR_IDS = Object.freeze(packs.map(p => p.id));
export const ROOMS = Object.freeze(['map', ...FLOOR_IDS.map(n => 'floor' + n)]);
export const validFloor = n => FLOOR_IDS.includes(n);
export const floorError = () => 'Floor must be ' + FLOOR_IDS.slice(0, -1).join(', ') + ' or ' + FLOOR_IDS.at(-1) + '.';
